import{_ as a,o as t,c as _,a3 as p}from"./chunks/framework.DdpBa4_E.js";const r="/ReadBooks/assets/image-035.BzbK6nbk.jpg",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/17-从1955年的“皇冠”到2005年的“雷克萨斯”.md","filePath":"books/xialiu-shehui/17-从1955年的“皇冠”到2005年的“雷克萨斯”.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/17-从1955年的“皇冠”到2005年的“雷克萨斯”.md"};function s(i,e,n,l,c,d){return t(),_("div",null,[...e[0]||(e[0]=[p('<h2 id="从1955年的-皇冠-到2005年的-雷克萨斯" tabindex="-1">从1955年的“皇冠”到2005年的“雷克萨斯” <a class="header-anchor" href="#从1955年的-皇冠-到2005年的-雷克萨斯" aria-label="Permalink to &quot;从1955年的“皇冠”到2005年的“雷克萨斯”&quot;">​</a></h2><p>我们注意到，向15%的上流阶层消费者销售价值15万日元的西服的销售额，与向45%的中流阶层消费者销售价值5万日元的西服，其销售额完全相同。这是理所当然的，人口只有后者的三分之一，而商品单价为后者的三倍，自然销售额等同。显然，从利润的角度来讲，针对上流阶层进行销售所获取的利润要多得多。如果上流阶层消费者每人购买20万日元的商品，则合计销售额总共多出75亿日元，这75亿日元恐怕都是纯利润吧（见图1-5）。</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>图1-5　假设向100万名男性销售西服……</p><p>在中流阶层人数逐渐减少的大趋势下，以中流阶层为消费的主要目标群并非最佳策略，而必须进一步瞄准上流阶层人群，因为只有这样，才有可能扩大销售额并且创出利润。现在的日本已经开始进入到这样的时代了。如此，从中流社会向等级化社会（即下流社会）的转变，使得原先的生产及经营模式失效，因而不得不探索和适应新的模式。</p><p>然而，日本的企业却存在一个致命的缺陷：整个体系都围绕着一个固定的模式运作，这个模式只是为了数量庞大的中流阶层生产和销售大量的商品，人们可以看到日本企业中的生产流水线都是按照这样的模式设计和设置的，加上企业员工人数过多，因而只能追求低利润率以保证扩大销售。</p><p>随着社会等级化的进一步加速，再也不可能像以前那样将目标消费群锁定在“中流”的人群身上，并为此目标而大量生产，必须要采取新的战略，例如针对上流阶层的消费者就必须要有适合“上流”的专门商品。</p><p>过去，以“中流”人群为目标消费群确实能够实现销售额及利润的最大化，因为向“中流”的人群销售10万日元的商品，假设转向“上流”人群却要实现同样的总销售额，就必须销售出80万日元的商品，这在那时是不可能的事情。</p><p>但是今后，只需针对“上流”人群销售30万日元的商品，就可以实现同样的总销售额，况且利润率会更高，而这样做却将变为可能。丰田汽车公司于2005年8月起开始生产和销售的“雷克萨斯”高级轿车正是这一战略的产物。2003年改装后重新营业的伊势丹百货绅士馆也大胆地迈出了高级化路线的一步。在此之前，百货商店的男士服饰铺面简直就是专为中流阶层的科长、部长们而设计的卖场，伊势丹绅士馆的改装可以说是在瞄准“上流”人群的基础上，成功地实现了差别化。</p><p>丰田汽车公司的“皇冠”轿车推出于1955年，与“1955年体制”同时登场，其后，从“花冠”到“光冠”再到“皇冠”，丰田汽车公司成长为一个产品线丰富的大型企业，其产品的逐步升级也正好为当时的阶层上升提示了一种经典的消费模式。从这个意义上说，“皇冠”轿车可以说是日本“一亿人口中流化时代”的一个象征。</p><p>如今，丰田汽车公司却专为一小部分富裕阶层推出了“雷克萨斯”高级轿车，毫无疑问，它不可能像“皇冠”车那样畅销，因为现在已经是“2005年体制”的时代了。</p><p>本书由“<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a>”整理，<a href="http://epubw.com" target="_blank" rel="noreferrer">ePUBw.COM</a> 提供最新最全的优质电子书下载！！！</p>',12)])])}const u=a(o,[["render",s]]);export{m as __pageData,u as default};
